
.action-menu-panel {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 4px;
  color: var(--text-primary);
}

.situation-section,
.actions-section {
  padding: 14px;
  border: 1px solid var(--border-color);
  border-radius: 10px;
  background: var(--bg-secondary);
}

.section-title,
.title-left,
.title-right,
.action-toolbar,
.toggle-btn,
.submit-mode,
.quick-list {
  display: flex;
  align-items: center;
}

.section-title {
  justify-content: space-between;
  gap: 10px;
  color: var(--text-secondary);
  font-size: 13px;
  font-weight: 650;
}

.title-left {
  gap: 8px;
  color: var(--text-accent);

  i {
    color: var(--accent-color);
  }
}

.title-right {
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 7px;
}

.section-badge,
.action-count {
  color: var(--text-secondary);
  font-size: 11px;
  font-weight: 500;
}

.section-badge {
  padding: 3px 8px;
  border: 1px solid var(--border-color);
  border-radius: 999px;

  &.mode-fresh {
    color: var(--text-accent);
    border-color: color-mix(in srgb, var(--accent-color) 42%, var(--border-color));
    background: color-mix(in srgb, var(--accent-color) 12%, transparent);
  }
}

.situation-content {
  margin: 11px 0 0;
  padding: 10px 12px;
  border-left: 2px solid var(--accent-color);
  border-radius: 0 8px 8px 0;
  background: color-mix(in srgb, var(--bg-primary) 78%, transparent);
  color: var(--text-primary);
  font-size: 13px;
  line-height: 1.65;
}

button {
  font: inherit;
}

.toggle-btn,
.refresh-btn,
.submit-mode button,
.quick-action {
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  background: color-mix(in srgb, var(--button-bg) 78%, transparent);
  cursor: pointer;
  transition:
    border-color 0.18s ease,
    color 0.18s ease,
    background 0.18s ease,
    transform 0.18s ease;

  &:hover:not(:disabled) {
    color: var(--text-primary);
    border-color: var(--border-active);
  }

  &:disabled {
    cursor: not-allowed;
    opacity: 0.48;
  }
}

.toggle-btn {
  gap: 5px;
  padding: 5px 8px;
  border-radius: 999px;
  font-size: 11px;

  &.active {
    color: var(--text-accent);
    border-color: var(--border-active);
    background: var(--button-active);
  }
}

.refresh-btn {
  width: 28px;
  height: 28px;
  padding: 0;
  border-radius: 7px;
}

.action-toolbar {
  justify-content: space-between;
  gap: 10px;
  margin-top: 12px;
  padding-top: 10px;
  border-top: 1px solid var(--border-color);
}

.action-count.muted {
  color: color-mix(in srgb, var(--text-secondary) 72%, transparent);
}

.submit-mode {
  padding: 2px;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  background: color-mix(in srgb, var(--bg-primary) 72%, transparent);

  button {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    padding: 5px 9px;
    border: 0;
    border-radius: 6px;
    background: transparent;
    font-size: 11px;

    &.active {
      color: var(--text-accent);
      background: var(--button-active);
      box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent-color) 35%, transparent);
    }
  }
}

.status-banner {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  margin-top: 12px;
  padding: 9px 11px;
  border: 1px solid var(--border-color);
  border-radius: 9px;
  font-size: 11px;

  > i {
    margin-top: 2px;
  }

  div {
    display: grid;
    gap: 2px;
  }

  strong {
    color: var(--text-primary);
  }

  span {
    color: var(--text-secondary);
  }

  &.warn {
    border-color: color-mix(in srgb, #d6a44d 45%, var(--border-color));
    background: color-mix(in srgb, #d6a44d 9%, transparent);

    > i {
      color: #d6a44d;
    }
  }

  &.info {
    border-color: color-mix(in srgb, #69a9d6 38%, var(--border-color));
    background: color-mix(in srgb, #69a9d6 8%, transparent);

    > i {
      color: #69a9d6;
    }
  }
}

.action-list {
  display: grid;
  gap: 8px;
  margin-top: 12px;
}

.action-row {
  --action-color: var(--accent-color);

  display: grid;
  grid-template-columns: 38px minmax(0, 1fr) auto 14px;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 9px 11px;
  border: 1px solid color-mix(in srgb, var(--action-color) 30%, var(--border-color));
  border-radius: 10px;
  color: var(--text-primary);
  text-align: left;
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--action-color) 10%, transparent), transparent 36%),
    color-mix(in srgb, var(--bg-primary) 82%, transparent);
  cursor: pointer;
  transition:
    transform 0.18s ease,
    border-color 0.18s ease,
    background 0.18s ease;

  &:hover:not(:disabled) {
    transform: translateY(-1px);
    border-color: color-mix(in srgb, var(--action-color) 58%, var(--border-color));
  }

  &:focus-visible {
    outline: 2px solid color-mix(in srgb, var(--action-color) 60%, transparent);
    outline-offset: 2px;
  }

  &:disabled {
    cursor: not-allowed;
    opacity: 0.56;
  }

  &.type-探索 {
    --action-color: #62c6a7;
  }

  &.type-交涉 {
    --action-color: #74aee8;
  }

  &.type-战斗 {
    --action-color: #db786e;
  }

  &.type-修炼 {
    --action-color: #8dcfd1;
  }

  &.type-整备 {
    --action-color: #d8a85b;
  }

  &.type-亲密 {
    --action-color: #d782a6;
  }
}

.action-icon {
  display: grid;
  width: 34px;
  aspect-ratio: 1;
  place-items: center;
  border-radius: 9px;
  color: color-mix(in srgb, var(--action-color) 92%, white);
  background: color-mix(in srgb, var(--action-color) 18%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--action-color) 26%, transparent);
}

.action-copy {
  display: grid;
  min-width: 0;
  gap: 4px;
}

.action-text {
  overflow-wrap: anywhere;
  font-size: 13px;
  font-weight: 620;
  line-height: 1.45;
}

.action-hint {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--text-secondary);
  font-size: 11px;
  line-height: 1.4;

  i {
    color: var(--action-color);
    font-size: 9px;
  }
}

.action-type {
  padding: 3px 7px;
  border-radius: 999px;
  color: var(--action-color);
  background: color-mix(in srgb, var(--action-color) 12%, transparent);
  font-size: 10px;
  white-space: nowrap;
}

.action-affordance {
  color: color-mix(in srgb, var(--action-color) 72%, var(--text-secondary));
  font-size: 10px;
}

.no-actions {
  display: grid;
  justify-items: center;
  gap: 6px;
  margin-top: 12px;
  padding: 18px 12px;
  border: 1px dashed var(--border-color);
  border-radius: 10px;
  color: var(--text-secondary);

  i {
    color: var(--accent-color);
  }

  p {
    margin: 0;
    font-size: 12px;
  }
}

.quick-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid var(--border-color);
}

.quick-label {
  color: var(--text-secondary);
  font-size: 11px;
  white-space: nowrap;
}

.quick-list {
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 7px;
}

.quick-action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 6px 10px;
  border-radius: 8px;
  font-size: 11px;

  i {
    color: var(--accent-color);
  }
}

@media (max-width: 520px) {
  .action-menu-panel {
    gap: 10px;
    padding: 0;
  }

  .situation-section,
  .actions-section {
    padding: 10px;
    border-radius: 8px;
  }

  .action-heading,
  .action-toolbar,
  .quick-actions {
    align-items: flex-start;
    flex-direction: column;
  }

  .title-right,
  .quick-list {
    width: 100%;
    justify-content: flex-start;
  }

  .action-toolbar {
    gap: 8px;
  }

  .action-row {
    grid-template-columns: 32px minmax(0, 1fr) auto;
    gap: 7px;
    padding: 8px;
  }

  .action-icon {
    width: 30px;
  }

  .action-type {
    grid-column: 2;
    justify-self: start;
  }

  .action-affordance {
    grid-column: 3;
    grid-row: 1 / span 2;
  }

  .quick-action {
    flex: 1 1 58px;
  }
}
