
.peace-panel {
  display: grid;
  gap: 14px;
  color: var(--text-primary);
}
.state-card,
.burden-section,
.result-section,
.residual-section,
.tribulation-result,
.advice-card {
  border: 1px solid var(--line-subtle);
  border-radius: 14px;
  background: color-mix(in srgb, var(--reading-surface) 92%, transparent);
  box-shadow: 0 12px 30px color-mix(in srgb, var(--stage-shadow) 22%, transparent);
}
.state-card {
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: center;
  gap: 15px;
  padding: 20px;
}
.state-icon {
  display: grid;
  place-items: center;
  width: 54px;
  height: 54px;
  border-radius: 50%;
  color: var(--jade);
  background: color-mix(in srgb, var(--jade) 13%, transparent);
  font-size: 22px;
}
.state-icon.recovery {
  color: #e6b867;
  background: rgba(230, 184, 103, 0.13);
}
.state-icon.critical {
  color: var(--semantic-danger);
  background: color-mix(in srgb, var(--semantic-danger) 13%, transparent);
}
.state-copy {
  display: grid;
  gap: 3px;
}
.state-copy > span {
  color: var(--text-secondary);
  font-size: 10px;
  letter-spacing: 0.13em;
}
.state-copy strong {
  color: var(--jade);
  font-size: 21px;
}
.state-card.recovery .state-copy strong {
  color: #e6b867;
}
.state-copy p,
.advice-card p,
.tribulation-result p {
  margin: 0;
  color: var(--text-secondary);
  font-size: 12px;
}
.burden-section,
.result-section,
.residual-section,
.tribulation-result,
.advice-card {
  padding: 14px 16px;
}
.section-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 11px;
}
.section-heading span,
.advice-card > span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 13px;
  font-weight: 700;
}
.section-heading i,
.advice-card i {
  color: var(--gold);
}
.section-heading b {
  color: var(--gold);
}
.burden-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 9px;
}
.burden-card {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px;
  border: 1px solid var(--line-subtle);
  border-radius: 11px;
}
.burden-card > i {
  font-size: 17px;
}
.burden-card > div {
  display: grid;
  gap: 2px;
}
.burden-card small {
  color: var(--text-secondary);
  font-size: 9px;
}
.burden-card b {
  font-size: 13px;
}
.tone-clear i,
.tone-clear b {
  color: var(--jade);
}
.tone-steady i,
.tone-steady b {
  color: var(--semantic-info);
}
.tone-strained i,
.tone-strained b {
  color: #e8a84c;
}
.tone-critical i,
.tone-critical b {
  color: var(--semantic-danger);
}
.result-section {
  border-color: color-mix(in srgb, var(--gold) 34%, var(--line-subtle));
}
.result-section > p {
  display: grid;
  grid-template-columns: 42px 1fr;
  gap: 8px;
  margin: 7px 0;
  color: var(--text-secondary);
  font-size: 12px;
}
.result-section > p small,
.result-list > small {
  color: var(--gold);
}
.result-list {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  margin-top: 9px;
}
.result-list > small {
  margin-right: 4px;
}
.result-list span {
  padding: 4px 8px;
  border-radius: 8px;
  color: var(--text-secondary);
  background: color-mix(in srgb, var(--semantic-danger) 9%, transparent);
  font-size: 10px;
}
.result-list.aftermath span {
  background: color-mix(in srgb, var(--gold) 9%, transparent);
}
.residual-list {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}
.residual-list span {
  display: inline-flex;
  gap: 7px;
  padding: 6px 9px;
  border-radius: 8px;
  color: var(--text-secondary);
  background: color-mix(in srgb, var(--semantic-danger) 9%, transparent);
  font-size: 10px;
}
.residual-list b {
  color: var(--text-primary);
}
.tribulation-result {
  display: grid;
  gap: 5px;
}
.advice-card {
  display: grid;
  gap: 8px;
  border-style: dashed;
}
@media (max-width: 760px) {
  .peace-panel {
    gap: 10px;
  }
  .state-card,
  .burden-section,
  .result-section,
  .residual-section,
  .tribulation-result,
  .advice-card {
    padding: 12px;
    border-radius: 11px;
  }
  .burden-card {
    display: grid;
    justify-items: center;
    gap: 5px;
    padding: 10px 5px;
    text-align: center;
  }
}
