
.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 20px 16px 12px 16px;
  min-height: 80px;
  background: var(--header-bg);
  border-bottom: 1px solid var(--border-color);

  .header-left {
    display: flex;
    gap: 8px;
    align-items: center;
  }

  .collapse-btn,
  .theme-btn,
  .preset-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    background: var(--button-bg);
    border: 1px solid var(--border-color);
    border-radius: 6px;
    color: var(--text-accent);
    cursor: pointer;
    transition: all 0.2s;

    &:hover {
      background: var(--button-hover);
      color: var(--text-primary);
      border-color: var(--border-active);
    }

    i {
      font-size: 12px;
    }
  }

  .location-info {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 6px;
    margin-left: auto;
    padding: 5px 8px;
    background: transparent;
    border: 1px solid transparent;
    border-radius: 8px;
    cursor: pointer;
    transition:
      background 0.2s,
      border-color 0.2s,
      box-shadow 0.2s,
      transform 0.2s;

    &:hover {
      background: var(--button-bg);
      border-color: var(--border-color);
      box-shadow: 0 0 16px rgba(255, 255, 255, 0.04);
      transform: translateY(-1px);
    }

    &:active {
      transform: translateY(0);
    }

    .danger-badge {
      font-size: 10px;
      padding: 2px 6px;
      border-radius: 10px;
      color: #fff;
    }

    .location {
      display: flex;
      align-items: center;
      gap: 8px;
      text-align: right;

      .location-hierarchy {
        display: flex;
        align-items: center;
        gap: 4px;

        .location-parent {
          font-size: 11px;
          opacity: 0.7;
        }

        .location-separator {
          font-size: 11px;
          opacity: 0.5;
        }

        .location-current {
          font-size: 13px;
          font-weight: 500;
        }
      }
    }
  }
}

// 手机端适配
@media screen and (max-width: 480px) {
  .header {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    gap: 8px;
    padding: 8px;
    min-height: 58px;

    .header-left {
      gap: 4px;
      min-width: 0;
    }

    .collapse-btn,
    .theme-btn,
    .preset-btn {
      width: 26px;
      height: 26px;

      i {
        font-size: 11px;
      }
    }

    .location-info {
      width: 100%;
      min-width: 0;
      margin-left: 0;
      padding: 3px 4px;
      overflow: hidden;

      .danger-badge {
        font-size: 9px;
        padding: 2px 5px;
      }

      .location {
        width: 100%;
        min-width: 0;
        justify-content: flex-end;
        gap: 3px;

        > i {
          flex: 0 0 auto;
          font-size: 11px;
        }

        .location-hierarchy {
          min-width: 0;
          max-width: 100%;
          gap: 2px;
          overflow: hidden;
          white-space: nowrap;

          .location-parent {
            flex: 0 1 auto;
            min-width: 0;
            overflow: hidden;
            font-size: 9px;
            text-overflow: ellipsis;
          }

          .location-current {
            flex: 0 1 auto;
            min-width: 0;
            overflow: hidden;
            font-size: 10px;
            text-overflow: ellipsis;
          }
        }
      }
    }
  }
}

.header.compact-layout {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 8px;
  padding: 8px;
  min-height: 58px;

  .header-left {
    gap: 4px;
    min-width: 0;
  }

  .collapse-btn,
  .theme-btn,
  .preset-btn {
    width: 26px;
    height: 26px;

    i {
      font-size: 11px;
    }
  }

  .location-info {
    width: 100%;
    min-width: 0;
    margin-left: 0;
    padding: 3px 4px;
    overflow: hidden;

    .danger-badge {
      padding: 2px 5px;
      font-size: 9px;
    }

    .location {
      width: 100%;
      min-width: 0;
      justify-content: flex-end;
      gap: 3px;

      > i {
        flex: 0 0 auto;
        font-size: 11px;
      }

      .location-hierarchy {
        min-width: 0;
        max-width: 100%;
        gap: 2px;
        overflow: hidden;
        white-space: nowrap;

        .location-parent,
        .location-current {
          flex: 0 1 auto;
          min-width: 0;
          overflow: hidden;
          text-overflow: ellipsis;
        }

        .location-parent {
          font-size: 9px;
        }

        .location-current {
          font-size: 10px;
        }
      }
    }
  }
}

@media screen and (max-width: 240px) {
  .header {
    .collapse-btn,
    .theme-btn,
    .preset-btn {
      width: 24px;
      height: 24px;
    }

    .location-info .location .location-hierarchy {
      .location-parent,
      .location-separator {
        display: none;
      }
    }
  }
}

.header.ultra-compact-layout {
  .collapse-btn,
  .theme-btn,
  .preset-btn {
    width: 24px;
    height: 24px;
  }

  .location-info .location .location-hierarchy {
    .location-parent,
    .location-separator {
      display: none;
    }
  }
}
