
.battle-panel {
  display: grid;
  gap: 14px;
  color: var(--text-primary);
}
.battle-header,
.momentum-card,
.info-card,
.enemies-section,
.scene-strip,
.methods-strip {
  border: 1px solid var(--line-subtle);
  border-radius: 14px;
  background: color-mix(in srgb, var(--reading-surface) 92%, transparent);
  box-shadow: 0 12px 30px color-mix(in srgb, var(--stage-shadow) 22%, transparent);
}
.battle-header {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 13px;
  padding: 15px 17px;
}
.phase-mark {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border-radius: 12px;
  color: #f3c873;
  background: rgba(192, 75, 55, 0.17);
}
.phase-copy {
  display: grid;
  gap: 2px;
  min-width: 0;
}
.phase-copy strong {
  color: #f0c779;
  font-size: 18px;
}
.phase-copy > span:last-child {
  overflow: hidden;
  color: var(--text-secondary);
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.eyebrow {
  color: var(--text-secondary);
  font-size: 10px;
  letter-spacing: 0.14em;
}
.round-seal {
  display: grid;
  place-items: center;
  min-width: 48px;
  padding: 6px 10px;
  border: 1px solid color-mix(in srgb, var(--gold) 38%, transparent);
  border-radius: 10px;
}
.round-seal small {
  color: var(--text-secondary);
  font-size: 9px;
}
.round-seal b {
  color: var(--gold);
  font-size: 19px;
}
.momentum-card,
.info-card,
.enemies-section {
  padding: 14px 16px;
}
.section-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 12px;
}
.section-heading > span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 13px;
  font-weight: 700;
}
.section-heading i {
  color: var(--gold);
}
.section-heading small {
  color: var(--text-secondary);
  font-size: 10px;
}
.section-heading > b {
  color: var(--gold);
  font-size: 12px;
}
.momentum-track {
  position: relative;
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 6px;
}
.momentum-track::before {
  position: absolute;
  top: 8px;
  right: 8%;
  left: 8%;
  height: 1px;
  content: '';
  background: var(--line-subtle);
}
.momentum-step {
  z-index: 1;
  display: grid;
  justify-items: center;
  gap: 6px;
  color: var(--text-secondary);
  text-align: center;
}
.step-dot {
  width: 17px;
  height: 17px;
  border: 3px solid color-mix(in srgb, var(--reading-surface) 85%, #000);
  border-radius: 50%;
  background: var(--line-subtle);
}
.momentum-step.passed .step-dot {
  background: color-mix(in srgb, var(--semantic-danger) 52%, var(--gold));
}
.momentum-step.active {
  color: var(--text-primary);
  font-weight: 700;
}
.momentum-step.active .step-dot {
  background: var(--gold);
  box-shadow: 0 0 12px color-mix(in srgb, var(--gold) 72%, transparent);
}
.momentum-step small {
  font-size: 10px;
}
.evidence-row,
.scene-strip,
.methods-strip {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 7px;
}
.evidence-row {
  margin-top: 12px;
}
.evidence-row span,
.scene-tag,
.methods-strip > span:not(.strip-title) {
  padding: 4px 8px;
  border-radius: 999px;
  color: var(--text-secondary);
  background: color-mix(in srgb, var(--reading-surface) 76%, var(--line-subtle));
  font-size: 10px;
}
.battle-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}
.objective-row {
  display: grid;
  grid-template-columns: 42px 1fr;
  gap: 9px;
  padding: 9px 0;
  border-top: 1px solid var(--line-subtle);
}
.objective-row:first-of-type {
  border-top: 0;
}
.objective-row small {
  color: var(--text-secondary);
}
.objective-row.mine small {
  color: var(--jade);
}
.objective-row.enemy small {
  color: var(--semantic-danger);
}
.burden-list {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}
.burden-item {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 3px 7px;
  padding: 9px;
  border: 1px solid var(--line-subtle);
  border-radius: 10px;
}
.burden-item i {
  grid-row: 1 / 3;
  align-self: center;
}
.burden-item span {
  color: var(--text-secondary);
  font-size: 10px;
}
.burden-item b {
  font-size: 12px;
}
.tone-clear i,
.tone-clear b {
  color: var(--jade);
}
.tone-steady i,
.tone-steady b {
  color: var(--semantic-info);
}
.tone-strained i,
.tone-strained b {
  color: #e8a84c;
}
.tone-critical i,
.tone-critical b {
  color: var(--semantic-danger);
}
.scene-strip,
.methods-strip {
  padding: 10px 13px;
}
.strip-title {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-right: 3px;
  color: var(--text-secondary);
  font-size: 11px;
}
.strip-title i {
  color: var(--gold);
}
.info-card ul {
  display: grid;
  gap: 7px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.info-card li {
  position: relative;
  padding-left: 14px;
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.45;
}
.info-card li::before {
  position: absolute;
  top: 0.55em;
  left: 0;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  content: '';
}
.opportunity-card li::before {
  background: var(--jade);
  box-shadow: 0 0 7px color-mix(in srgb, var(--jade) 70%, transparent);
}
.danger-card li::before {
  background: var(--semantic-danger);
  box-shadow: 0 0 7px color-mix(in srgb, var(--semantic-danger) 70%, transparent);
}
.empty-copy,
.empty-enemies {
  margin: 0;
  color: var(--text-secondary);
  font-size: 11px;
  font-style: italic;
}
.enemy-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}
.enemy-card {
  display: grid;
  gap: 9px;
  padding: 12px;
  border: 1px solid var(--line-subtle);
  border-radius: 12px;
  background: color-mix(in srgb, var(--reading-surface) 88%, transparent);
}
.enemy-card.inactive {
  opacity: 0.58;
}
.enemy-topline {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
}
.enemy-topline > div {
  display: grid;
  gap: 2px;
}
.enemy-topline strong {
  font-size: 14px;
}
.enemy-topline > div span {
  color: var(--text-secondary);
  font-size: 10px;
}
.enemy-state {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--text-secondary);
  font-size: 10px;
}
.standing-badge {
  width: fit-content;
  padding: 4px 8px;
  border-radius: 999px;
  font-size: 10px;
}
.standing-safe,
.standing-easy {
  color: var(--jade);
  background: color-mix(in srgb, var(--jade) 12%, transparent);
}
.standing-equal {
  color: var(--gold);
  background: color-mix(in srgb, var(--gold) 12%, transparent);
}
.standing-hard,
.standing-deadly {
  color: var(--semantic-danger);
  background: color-mix(in srgb, var(--semantic-danger) 12%, transparent);
}
.enemy-purpose {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 7px;
  margin: 0;
  color: var(--text-secondary);
  font-size: 11px;
}
.enemy-purpose small,
.enemy-detail small {
  color: var(--gold);
}
.enemy-detail {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}
.enemy-detail small {
  width: 100%;
  font-size: 9px;
}
.enemy-detail span {
  padding: 3px 7px;
  border-radius: 7px;
  color: var(--text-secondary);
  background: color-mix(in srgb, var(--semantic-danger) 9%, transparent);
  font-size: 9px;
}
.enemy-detail.openings span {
  background: color-mix(in srgb, var(--jade) 9%, transparent);
}
.methods-strip .mine {
  border: 1px solid color-mix(in srgb, var(--jade) 28%, transparent);
}
.methods-strip .enemy {
  border: 1px solid color-mix(in srgb, var(--semantic-danger) 28%, transparent);
}
@media (max-width: 760px) {
  .battle-panel {
    gap: 10px;
  }
  .battle-header,
  .momentum-card,
  .info-card,
  .enemies-section {
    padding: 11px 12px;
    border-radius: 11px;
  }
  .battle-grid,
  .enemy-grid {
    grid-template-columns: 1fr;
    gap: 10px;
  }
  .burden-list {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .burden-item {
    grid-template-columns: 1fr;
    justify-items: center;
    text-align: center;
  }
  .burden-item i {
    grid-row: auto;
  }
  .momentum-step small {
    max-width: 3em;
  }
}
